// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent);
        vm.prank(actor);
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }
        assertTrue(ok);
        // General rule: after a successful full withdrawal, the credited balance is zero.
        assertTrue(c.balances(actor) == 0);
    }
}
